/**
 * The water material — a code-split chunk.
 *
 * A registered chunk manifest module (MANIFEST_MODULES in
 * tooling/check-shader-imports.mjs, `chunk: true` + ALLOWLIST): the only
 * legal import site for `ShaderMaterial` on this path. Loaded exclusively by
 * dynamic `import()` from water.ts, and only for a world with a water body,
 * so a dry world never pays for it.
 *
 * What the material does is what the profile says a surface is
 * (`specs/veml/profiles/water.md`, Seen from above): the shallow colour
 * shading toward the deep colour by the depth of what lies beneath, moving
 * by `waves`, and cut away inside a blocker. Depth arrives per vertex (the
 * scene probes the bed under each vertex and writes a `depth` attribute), so
 * the shader needs no depth texture and no second pass.
 *
 * The shader is authored inline in both GLSL and WGSL and selected by engine
 * kind, for the same reason the sky chunk is: WebGPU consumes WGSL natively,
 * and a GLSL material there would fetch a transpiler from a CDN.
 */
import { ShaderMaterial } from '@babylonjs/core/Materials/shaderMaterial';
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { Color4 } from '@babylonjs/core/Maths/math.color';
import { Matrix, Vector4 } from '@babylonjs/core/Maths/math.vector';
import type { Scene } from '@babylonjs/core/scene';
import type { Material } from '@babylonjs/core/Materials/material';

/** The most blockers one surface cuts away in the shader; the volume test honours every blocker regardless. */
export const WATER_SHADER_BLOCKER_MAX = 8;

export interface WaterRgba {
  r: number;
  g: number;
  b: number;
  a: number;
}

/** A blocker as the shader sees it: a world→local matrix and the box's half extents. */
export interface WaterBlockerBox {
  inverse: Matrix;
  half: { x: number; y: number; z: number };
}

export interface WaterMaterialSpec {
  color: WaterRgba;
  deepColor: WaterRgba;
  /** Metres of depth at which the colour has become `deepColor`; 0 is opaque. */
  clarity: number;
  /** 0..1, how much the surface moves. */
  waves: number;
  blockers: readonly WaterBlockerBox[];
}

export interface WaterMaterialHandle {
  material: Material;
  /** Advance the wave animation; seconds since the world entered. */
  setTime(seconds: number): void;
  /** True once the shader compiled: the inline-shader guard. Never throws. */
  isReady(): boolean;
  dispose(): void;
}

export type WaterChunkModule = {
  createWaterMaterial(spec: WaterMaterialSpec, scene: Scene, engineKind?: string): WaterMaterialHandle;
};

const VERTEX_SOURCE_GLSL = `
precision highp float;
attribute vec3 position;
attribute float depth;
uniform mat4 worldViewProjection;
uniform mat4 world;
uniform float time;
uniform float waves;
varying float vDepth;
varying vec3 vWorldPos;
void main(void) {
  vec4 wp = world * vec4(position, 1.0);
  float lift = waves * 0.15 * 0.5 * (sin(wp.x * 0.8 + time * 1.3) + sin(wp.z * 0.6 + time * 0.9));
  wp.y += lift;
  vWorldPos = wp.xyz;
  vDepth = depth;
  gl_Position = worldViewProjection * vec4(position.x, position.y + lift, position.z, 1.0);
}`;

const FRAGMENT_SOURCE_GLSL = `
precision highp float;
varying float vDepth;
varying vec3 vWorldPos;
uniform vec4 shallowColor;
uniform vec4 deepColor;
uniform float clarity;
uniform float waves;
uniform float time;
uniform float blockerCount;
uniform mat4 blockerInverse[${WATER_SHADER_BLOCKER_MAX}];
uniform vec4 blockerHalf[${WATER_SHADER_BLOCKER_MAX}];
void main(void) {
  for (int i = 0; i < ${WATER_SHADER_BLOCKER_MAX}; i++) {
    if (float(i) < blockerCount) {
      vec3 l = (blockerInverse[i] * vec4(vWorldPos, 1.0)).xyz;
      if (all(lessThanEqual(abs(l), blockerHalf[i].xyz))) discard;
    }
  }
  float t = clarity > 0.0 ? clamp(vDepth / clarity, 0.0, 1.0) : 1.0;
  vec4 col = mix(shallowColor, deepColor, t);
  col.rgb += 0.04 * waves * sin(vWorldPos.x * 2.0 + vWorldPos.z * 1.7 + time * 2.0);
  gl_FragColor = col;
}`;

const VERTEX_SOURCE_WGSL = `
attribute position: vec3f;
attribute depth: f32;
uniform worldViewProjection: mat4x4f;
uniform world: mat4x4f;
uniform time: f32;
uniform waves: f32;
varying vDepth: f32;
varying vWorldPos: vec3f;
@vertex
fn main(input: VertexInputs) -> FragmentInputs {
  var wp: vec4f = uniforms.world * vec4f(vertexInputs.position, 1.0);
  var lift: f32 = uniforms.waves * 0.15 * 0.5 * (sin(wp.x * 0.8 + uniforms.time * 1.3) + sin(wp.z * 0.6 + uniforms.time * 0.9));
  wp.y = wp.y + lift;
  vertexOutputs.vWorldPos = wp.xyz;
  vertexOutputs.vDepth = vertexInputs.depth;
  vertexOutputs.position = uniforms.worldViewProjection * vec4f(vertexInputs.position.x, vertexInputs.position.y + lift, vertexInputs.position.z, 1.0);
}`;

const FRAGMENT_SOURCE_WGSL = `
varying vDepth: f32;
varying vWorldPos: vec3f;
uniform shallowColor: vec4f;
uniform deepColor: vec4f;
uniform clarity: f32;
uniform waves: f32;
uniform time: f32;
uniform blockerCount: f32;
uniform blockerInverse: array<mat4x4f, ${WATER_SHADER_BLOCKER_MAX}>;
uniform blockerHalf: array<vec4f, ${WATER_SHADER_BLOCKER_MAX}>;
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  for (var i: i32 = 0; i < ${WATER_SHADER_BLOCKER_MAX}; i++) {
    if (f32(i) < uniforms.blockerCount) {
      let l: vec3f = (uniforms.blockerInverse[i] * vec4f(input.vWorldPos, 1.0)).xyz;
      if (all(abs(l) <= uniforms.blockerHalf[i].xyz)) { discard; }
    }
  }
  var t: f32 = 1.0;
  if (uniforms.clarity > 0.0) { t = clamp(input.vDepth / uniforms.clarity, 0.0, 1.0); }
  var col: vec4f = mix(uniforms.shallowColor, uniforms.deepColor, t);
  let shimmer: f32 = 0.04 * uniforms.waves * sin(input.vWorldPos.x * 2.0 + input.vWorldPos.z * 1.7 + uniforms.time * 2.0);
  col = vec4f(col.rgb + vec3f(shimmer), col.a);
  fragmentOutputs.color = col;
}`;

export interface WaterShaderSources {
  shaderLanguage: ShaderLanguage;
  vertexSource: string;
  fragmentSource: string;
}

/** WGSL on WebGPU, GLSL on the WebGL2 floor. Pure, so the selection is unit-tested without a GPU. */
export function selectWaterShaderSources(engineKind?: string): WaterShaderSources {
  if (engineKind === 'webgpu') {
    return { shaderLanguage: ShaderLanguage.WGSL, vertexSource: VERTEX_SOURCE_WGSL, fragmentSource: FRAGMENT_SOURCE_WGSL };
  }
  return { shaderLanguage: ShaderLanguage.GLSL, vertexSource: VERTEX_SOURCE_GLSL, fragmentSource: FRAGMENT_SOURCE_GLSL };
}

export function createWaterMaterial(spec: WaterMaterialSpec, scene: Scene, engineKind?: string): WaterMaterialHandle {
  const sources = selectWaterShaderSources(engineKind);
  const material = new ShaderMaterial(
    'water:material',
    scene,
    { vertexSource: sources.vertexSource, fragmentSource: sources.fragmentSource },
    {
      attributes: ['position', 'depth'],
      uniforms: [
        'worldViewProjection',
        'world',
        'time',
        'waves',
        'shallowColor',
        'deepColor',
        'clarity',
        'blockerCount',
        'blockerInverse',
        'blockerHalf',
      ],
      needAlphaBlending: true,
      shaderLanguage: sources.shaderLanguage,
    },
  );
  // Seen from below as well as above: the same surface, no culling.
  material.backFaceCulling = false;

  const c4 = (c: WaterRgba): Color4 => new Color4(c.r, c.g, c.b, c.a);
  material.setColor4('shallowColor', c4(spec.color));
  material.setColor4('deepColor', c4(spec.deepColor));
  material.setFloat('clarity', spec.clarity);
  material.setFloat('waves', spec.waves);
  material.setFloat('time', 0);

  // The shader cuts away at most WATER_SHADER_BLOCKER_MAX boxes; the arrays
  // are always full-length so the uniform layout never changes.
  const boxes = spec.blockers.slice(0, WATER_SHADER_BLOCKER_MAX);
  const inverses: Matrix[] = [];
  const halves: Vector4[] = [];
  for (let i = 0; i < WATER_SHADER_BLOCKER_MAX; i += 1) {
    const b = boxes[i];
    inverses.push(b ? b.inverse : Matrix.Identity());
    halves.push(b ? new Vector4(b.half.x, b.half.y, b.half.z, 0) : new Vector4(0, 0, 0, 0));
  }
  material.setFloat('blockerCount', boxes.length);
  material.setMatrices('blockerInverse', inverses);
  material.setArray4(
    'blockerHalf',
    halves.flatMap((h) => [h.x, h.y, h.z, h.w]),
  );

  return {
    material,
    setTime(seconds: number): void {
      material.setFloat('time', seconds);
    },
    isReady(): boolean {
      try {
        return material.isReady();
      } catch {
        return false;
      }
    },
    dispose(): void {
      material.dispose();
    },
  };
}
